package net.fabricmc.fabric.api.client.screen.v1;
import java.util.Map;
import java.util.WeakHashMap;

import net.fabricmc.fabric.api.event.Event;
import net.fabricmc.fabric.api.event.EventFactory;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.Screen;

/** Fabric API: screens opening, drawing, ticking and closing (Omniloader stand-in; generated by tools/gen-fabric-events.py). */
public final class ScreenEvents {
    private ScreenEvents() {}

    /** Per-screen events, forgotten when the screen goes away. */
    private static final Map<Screen, Map<String, Event<?>>> PER_SCREEN = new WeakHashMap<>();

    @SuppressWarnings("unchecked")
    private static synchronized <T> Event<T> of(Screen s, String k, java.util.function.Supplier<Event<T>> f) {
        return (Event<T>) PER_SCREEN.computeIfAbsent(s, x -> new java.util.HashMap<>()).computeIfAbsent(k, x -> f.get());
    }

    /** Omniloader: drop a screen's per-screen listeners (Fabric does this each time a screen is set up again). */
    public static synchronized void clear(Screen s) { PER_SCREEN.remove(s); }

    /** Omniloader: the per-screen event if anyone registered on it. */
    @SuppressWarnings("unchecked")
    public static synchronized <T> Event<T> peek(Screen s, String k) { var m = PER_SCREEN.get(s); return m == null ? null : (Event<T>) m.get(k); }

    public static final Event<BeforeInit> BEFORE_INIT = EventFactory.createArrayBacked(BeforeInit.class, ls -> (client, screen, scaledWidth, scaledHeight) -> { for (BeforeInit l : ls) l.beforeInit(client, screen, scaledWidth, scaledHeight); });
    public static final Event<AfterInit> AFTER_INIT = EventFactory.createArrayBacked(AfterInit.class, ls -> (client, screen, scaledWidth, scaledHeight) -> { for (AfterInit l : ls) l.afterInit(client, screen, scaledWidth, scaledHeight); });
    public static Event<Remove> remove(Screen forScreen) { return of(forScreen, "remove", () -> EventFactory.createArrayBacked(Remove.class, ls -> screen -> { for (Remove l : ls) l.onRemove(screen); })); }
    public static Event<BeforeRender> beforeRender(Screen forScreen) { return of(forScreen, "beforeRender", () -> EventFactory.createArrayBacked(BeforeRender.class, ls -> (screen, drawContext, mouseX, mouseY, tickDelta) -> { for (BeforeRender l : ls) l.beforeRender(screen, drawContext, mouseX, mouseY, tickDelta); })); }
    public static Event<AfterRender> afterRender(Screen forScreen) { return of(forScreen, "afterRender", () -> EventFactory.createArrayBacked(AfterRender.class, ls -> (screen, drawContext, mouseX, mouseY, tickDelta) -> { for (AfterRender l : ls) l.afterRender(screen, drawContext, mouseX, mouseY, tickDelta); })); }
    public static Event<BeforeTick> beforeTick(Screen forScreen) { return of(forScreen, "beforeTick", () -> EventFactory.createArrayBacked(BeforeTick.class, ls -> screen -> { for (BeforeTick l : ls) l.beforeTick(screen); })); }
    public static Event<AfterTick> afterTick(Screen forScreen) { return of(forScreen, "afterTick", () -> EventFactory.createArrayBacked(AfterTick.class, ls -> screen -> { for (AfterTick l : ls) l.afterTick(screen); })); }

    @FunctionalInterface public interface BeforeInit { void beforeInit(Minecraft client, Screen screen, int scaledWidth, int scaledHeight); }
    @FunctionalInterface public interface AfterInit { void afterInit(Minecraft client, Screen screen, int scaledWidth, int scaledHeight); }
    @FunctionalInterface public interface Remove { void onRemove(Screen screen); }
    @FunctionalInterface public interface BeforeRender { void beforeRender(Screen screen, GuiGraphics drawContext, int mouseX, int mouseY, float tickDelta); }
    @FunctionalInterface public interface AfterRender { void afterRender(Screen screen, GuiGraphics drawContext, int mouseX, int mouseY, float tickDelta); }
    @FunctionalInterface public interface BeforeTick { void beforeTick(Screen screen); }
    @FunctionalInterface public interface AfterTick { void afterTick(Screen screen); }
}
